def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']

    alive_opponents = [o for o in opponents_status.values() if o.get('alive')]
    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    # Use only yesterday's immediate trace to infer pressure.
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    # If someone previously bid very high, they likely tried to lock supply.
    # If no one bid high, we can undercut slightly.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        # High pressure yesterday: bid enough to avoid getting squeezed.
        if my_status['hp'] > 3:
            target = DAILY_SALARY * 0.30
        else:
            target = DAILY_SALARY * 0.95
    else:
        # Moderate pressure: bid midrange but not maximal.
        # Undercut a bit relative to the best observed pressure.
        target = max(DAILY_SALARY * 0.50, min(DAILY_SALARY * 0.90, highest_prev_bid * 0.80 + 5.0))
        if my_status['hp'] <= 2:
            target = max(target, DAILY_SALARY * 0.85)

    # Budget and supply-aware cap: if supply is low, competition matters more.
    # Still keep within budget.
    if supply <= (MIN_SUPPLY + MAX_SUPPLY) / 2:
        target *= 1.10
    else:
        target *= 0.95

    bid = min(my_status['budget'], target)

    # Avoid pathological tiny bids when we have water need.
    # (If we are already low on hp/no_water_days, be more aggressive.)
    if my_status['no_water_days'] >= 2 or my_status['hp'] <= 2:
        bid = max(bid, min(my_status['budget'], DAILY_SALARY * 0.70))

    return float(max(0.0, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    day = day_context['day']
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    prev_bids = []
    stressed_opponents = 0
    rich_aggressive = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                stressed_opponents += 1
            if opp.get('budget', 0) >= 700:
                rich_aggressive += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(prev.get('bid', 0.0))

    if not alive_opponents:
        return float(min(budget, 18.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    capacity = supply / WATER_REQ
    low_supply = capacity < 2.0
    very_low_supply = capacity < 1.8
    high_supply = capacity >= 2.5

    emergency = hp <= 2 or no_water_days >= 2
    danger = hp <= 4 or no_water_days >= 1
    late_game = day >= 8

    if emergency:
        base = max(81.0, highest_prev + 3.0)
        if very_low_supply:
            base = max(base, 90.0)
        return float(min(budget, base))

    if danger:
        base = max(62.0, highest_prev + 2.0)
        if low_supply:
            base = max(base, 74.0)
        return float(min(budget, base))

    if high_supply and hp >= 6 and no_water_days == 0:
        base = 16.0
        if highest_prev > 0:
            base = min(28.0, max(base, avg_prev * 0.35))
        return float(min(budget, base))

    base = 34.0
    if low_supply:
        base = 48.0
    if highest_prev >= 120.0:
        base = max(base, 44.0)
    elif highest_prev >= 90.0:
        base = max(base, 40.0)
    elif highest_prev >= 60.0:
        base = max(base, highest_prev * 0.72)
    elif highest_prev > 0.0:
        base = max(base, highest_prev + 1.5)

    if stressed_opponents >= 2:
        base += 6.0
    if rich_aggressive >= 2 and low_supply:
        base += 8.0
    if late_game:
        base += 6.0
    if hp >= 8 and no_water_days == 0 and not low_supply:
        base -= 6.0

    reserve_floor = DAILY_SALARY * max(0, 10 - int(day)) * 0.18
    max_today = budget
    if budget > reserve_floor:
        max_today = max(0.0, budget - reserve_floor * 0.15)

    bid = min(max_today, base)
    bid = max(0.0, min(budget, bid))
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    my_current_hp = my_status['hp']
    my_current_budget = my_status['budget']
    current_day = day_context['day']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_current_budget, DAILY_SALARY * 0.2)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    bid = DAILY_SALARY * 0.5

    if my_current_hp <= 2:
        bid = DAILY_SALARY * 0.95
    elif my_current_hp <= 4:
        bid = max(bid, DAILY_SALARY * 0.75)

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        if highest_prev_bid >= DAILY_SALARY * 0.8:
            if my_current_hp <= 4:
                bid = max(bid, highest_prev_bid + 5)
            else:
                bid = max(bid, highest_prev_bid + 2)
        elif highest_prev_bid > DAILY_SALARY * 0.5:
            bid = max(bid, highest_prev_bid + 1)

    remaining_days = EPISODE_DAYS - current_day
    if remaining_days <= 2:
        if my_current_hp <= 5:
            bid = max(bid, DAILY_SALARY * 1.0)
        else:
            bid = max(bid, DAILY_SALARY * 0.8)

    final_bid = min(my_current_budget, bid)

    return round(final_bid, 2)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    # Calculate a baseline bid slightly higher than supply to compete for water
    target_bid = supply * 1.1

    # If HP is low, prioritize survival over budget
    if my_status['hp'] <= 3:
        target_bid = supply * 1.5

    # If no opponents, bid minimally
    if not alive_opponents:
        return min(my_status['budget'], WATER_REQ * 2)

    # Check yesterday's bids to gauge intensity
    yesterday_bids = [o['previous_trace']['bid'] for o in alive_opponents if o.get('previous_trace') and o['previous_trace'].get('bid') is not None]
    if yesterday_bids:
        max_prev = max(yesterday_bids)
        # If others are bidding very high, decide whether to contest or save
        if max_prev > DAILY_SALARY:
            target_bid = min(my_status['budget'], max_prev * 0.95)
        else:
            target_bid = max(target_bid, max_prev * 1.05)

    return float(min(my_status['budget'], target_bid))
